import {
  type AnyPgColumn,
  boolean,
  index,
  integer,
  jsonb,
  text,
  uniqueIndex,
  uuid,
} from 'drizzle-orm/pg-core';
import {
  alumniConsentToContacts,
  alumniCurrentStatuses,
  alumniUpdateSources,
} from '@takhti/contracts';
import { appendColumns, baseColumns } from '../../kernel/base-columns';
import { enumText, live } from '../../kernel/columns';
import { defineTable } from '../../kernel/define-table';
import { grades } from '../academics/academics.table';
import { branches } from '../organisation/branches.table';
import { students } from '../students/students.table';

/* The tables of M10 · Alumni. */

export const alumni = defineTable(
  'alumni',
  { module: 'M10', scope: 'org' },
  {
    ...baseColumns,
    studentId: uuid()
      .references((): AnyPgColumn => students.id)
      .notNull(),
    /** the branch they graduated from */
    branchId: uuid()
      .references((): AnyPgColumn => branches.id)
      .notNull(),
    graduationYear: integer().notNull(),
    lastGradeId: uuid()
      .references((): AnyPgColumn => grades.id)
      .notNull(),
    /** "SSC 1,045/1,200, A+" */
    boardResultSummary: text(),
    currentStatus: enumText(alumniCurrentStatuses).notNull().default('unknown'),
    /** college or university */
    institution: text(),
    fieldOfStudy: text(),
    occupation: text(),
    city: text(),
    phone: text(),
    email: text(),
    consentToContact: enumText(alumniConsentToContacts).notNull().default('not_asked'),
    /** name and achievement may appear on the school website */
    consentToShowcase: boolean().notNull().default(false),
    achievements: text(),
    notes: text(),
  },
  (t) => [
    uniqueIndex('alumni_student_uq').on(t.orgId, t.studentId).where(live(t)),
    index('alumni_graduation_year_idx').on(t.orgId, t.graduationYear),
  ],
);

/** A history of what an alumnus told the school, and when. */
export const alumniUpdates = defineTable(
  'alumni_updates',
  { module: 'M10', scope: 'org', appendOnly: true, staff: 'append' },
  {
    ...appendColumns,
    alumniId: uuid()
      .references((): AnyPgColumn => alumni.id)
      .notNull(),
    changes: jsonb().notNull(),
    source: enumText(alumniUpdateSources).notNull(),
  },
);
